async function retry(fn, { retries = 3, baseDelay = 20, factor = 2, signal }) {
  let attempt = 0;
  while (true) {
    if (signal?.aborted) throw new Error('Aborted');
    try {
      return await fn();
    } catch (err) {
      if (attempt++ >= retries) throw err;
      await new Promise(r => setTimeout(r, baseDelay * Math.pow(factor, attempt)));
    }
  }
}

