};

function get(obj, path, defaultValue) {
  const keys = path.replace(/\[(\d+)\]/g, '.$1').split('.');
  let curr = obj;
  for (const k of keys) {
    if (curr == null) return defaultValue;
    curr = curr[k];
  }
  return curr === undefined ? defaultValue : curr;
}

